data: {"level":1,"reviewed":{"level":1,"label":"concept","text":"ANOVA splits the total variation of the data into a part explained by group membership and a part left\ninside the groups. The ratio of the two, scaled by their degrees of freedom, is F. Large F means the group\nmeans differ more than the within-group noise would explain."},"hints_note":null}

